long compat_recvmmsg_time32(int fd, struct compat_mmsghdr __user *mmsg, unsigned int vlen, unsigned int flags, struct compat_timespec __user *timeout) {
    long ret = -EINVAL;
    struct mmsghdr __user *mmsgh = NULL;
    struct timespec ts = {0};
    struct timeval tv = {0};
    int i = 0;

    if (!access_ok(VERIFY_READ, mmsg, vlen * sizeof(struct compat_mmsghdr))) {
        return -EFAULT;
    }

    if (timeout) {
        if (get_user(ts.tv_sec, &timeout->tv_sec) || get_user(ts.tv_nsec, &timeout->tv_nsec)) {
            return -EFAULT;
        }
        if (ts.tv_nsec >= NSEC_PER_SEC) {
            return -EINVAL;
        }
        tv.tv_sec = ts.tv_sec;
        tv.tv_nsec = ts.tv_nsec;
    }

    mmsgh = kmalloc(vlen * sizeof(struct mmsghdr), GFP_KERNEL);
    if (!mmsgh) {
        return -ENOMEM;
    }

    for (i = 0; i < vlen; i++) {
        struct compat_mmsghdr cmmsg = {0};
        if (copy_from_user(&cmmsg, &mmsg[i], sizeof(struct compat_mmsghdr))) {
            ret = -EFAULT;
            goto out;
        }
        mmsgh[i].msg_hdr = (struct msghdr __user *)((unsigned long)cmmsg.msg_hdr);
        mmsgh[i].msg_len = cmmsg.msg_len;
    }

    ret = sys_recvmmsg(fd, mmsgh, vlen, flags, timeout ? &tv : NULL);

    for (i = 0; i < ret; i++) {
        struct compat_mmsghdr cmmsg = {0};
        if (copy_to_user(&mmsg[i], &cmmsg, sizeof(struct compat_mmsghdr))) {
            ret = -EFAULT;
            goto out;
        }
    }

out:
    kfree(mmsgh);
    return ret;
}
